using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEngine.EventSystems;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class ExtraUpgradeCheck{
 public static object Prepare(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");g.SetBuild(BuildPreset.Manual);g.TryStartRun(42);g.SetPaused(true);return "Wait one rendered frame, then Run";}
 public static object Open(){Click("ExtraUpgrades");return "Wait one frame, then Run";}
 public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var hud=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();var refresh=typeof(BokumyakuBattleHud).GetMethod("Refresh",BindingFlags.Instance|BindingFlags.NonPublic);var ink=typeof(RunSimulator).GetProperty("RunInk");ink.SetValue(g.Run,50000);var rows=new List<object>();if(GameObject.Find("UpgradeBleed")==null)throw new Exception("Open ExtraUpgrades and wait one rendered frame before Run");for(int i=5;i<7;i++){refresh.Invoke(hud,null);Canvas.ForceUpdateCanvases();int before=g.Run.UpgradeLevels[i],balance=g.Run.RunInk,cost=g.Run.UpgradeCost((UpgradeKind)i);Click(i==5?"UpgradeBleed":"UpgradeHarvest");rows.Add(new{slot=i,passed=g.Run.UpgradeLevels[i]==before+1&&g.Run.RunInk==balance-cost});}ink.SetValue(g.Run,0);refresh.Invoke(hud,null);int level=g.Run.UpgradeLevels[5];Click("UpgradeBleed");rows.Add(new{slot=5,passed=g.Run.UpgradeLevels[5]==level&&g.Run.RunInk==0});File.WriteAllText(Path.GetFullPath("../docs/evidence/extra-upgrade-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/extra-upgrade-panel.png"));return rows;}
 static void Click(string name){var b=GameObject.Find(name).GetComponent<UnityEngine.UI.Button>();var r=(RectTransform)b.transform;var data=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(data,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()!=b)throw new Exception("Blocked "+name);ExecuteEvents.Execute(b.gameObject,data,ExecuteEvents.pointerClickHandler);}
}



